public class Main {
    static int missing(int[] a) {
        int n = a.length;
        int expected = n * (n + 1) / 2;
        int actual = 0;
        for (int x : a) {
            actual += x;
        }
        return expected - actual;
    }

    public static void main(String[] args) {
        System.out.println(missing(new int[] {3, 0, 1}));
        System.out.println(missing(new int[] {9, 6, 4, 2, 3, 5, 7, 0, 1}));
    }
}
